export interface AuthConfig {
  apiKey: string;
  baseUrl: string;
}

export function buildAuthHeaders(config: AuthConfig): Record<string, string> {
  return {
    apiKey: config.apiKey,
    baseUrl: config.baseUrl,
  };
}
